INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1503997-ics353', 'stk-ahmelq', 'ICS 353', 'info', '{"desc": "ICS 353 Design and Analysis of Algorithms\nTerm: 181\nد. وصفي الخطيب\nالكتب المستخدمة:\n\nبشكل أساسي algorithms design and analysis للمؤلف محمد السويل\nمقتطفات من CLRS\nمقتطفات من Models of Computation Exploring the Power of Computing\n----\n\nالمقرر ممتع، وممتاز جداً ويُعتبر مع مقرر بنية البيانات (ICS202) من لُب تخصص علوم الحاسب، لا تستهين فيه أبداً خصوصاً لو كنت CS. المقرر يتطرق لـ 3 أبواب رئيسة:\n\nتحليل الخوارزميات\nطرق تصميم الخوارزميات\nمقدمة في النظرية الحاسوبية (computability theory)\nباختصار مواضيع المقرر هي كالآتي:\n\nالمفاهيم الأساسية للخوارزميات\n: مقدمة عامة وتعريف ماهي الخوارزمية، تعقيد الوقت والمساحة ترميز بيغ أوه، أوميغا، بيغ ثيتا، سمول أوه (سبق وكانت في ICS202)، كيف تحلل متوسط التعقيد الزمني والمساحي لخوارزمية أو في أسوء أو أفضل حالة. 1. بُنية الكومات (heaps) والمجموعات المتفرقة (disjoint sets):\n(بعضها سبق وكان في ICS202) بصراحة المفروض تكون مع مع مقرر بنية البيانات.\nحل علاقات الاستدعاء الذاتي\n(Recurrence Relations): فيه عدة طرق من ضمنها الـMaster Theorem، د. محمد السويل ما غطاها فكتابه للأسف لكن موجودة في CLRS 1. تصميم الخوارزميات\n: بالاستقراء (Induction)، وبالتقسيم والفتح (divide and conquer)، وبالبرمجة الديناميكية (dynamic programming)، وبالطريقة “الجشعة” (Greedy Algorithms) وإثباتات صحتها (proof).\nمقدمة في النظرية الحاسوبية:\nالمشكلات التي تنحل في تعقيد زمني بمعادلات غير متعددة الحدود P vs. NP، وآلة تورينغ (Turing machine).\n---\nشرح الدكتور كان وافي وكافي وأستزيده بقراءة الكتاب في نهاية الأسبوع وتدوين الملاحظات (تساعد كثيراً)، وإذا ما استصعب شيء لا أتغاضى عنه وابحث عنه على الشابكة.\nكتاب د.السويل ممتاز، إلا أنه في بعض المواضيع يُسهب لدرجة الملل، ويتغاضى عن مواضيع أخرى فيجحف بحقها. وللأسف لا يوجد أي حلول للتمارين (حتى للتمارين الفردية كما هي العادة في معظم الكتب) لتتأكد من صحة حلك.\nتخلل المقرر 4 واجبات منها 3 نظرية (حل)، والرابع واجب برمجي أشبه بالمشروع الصغير يتعاون فيه طالبان ويقدمان محاضرة عنه.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics-353-design-and-analysis-of-algorithms/120847/4", "user": "ahmelq", "ts": 1545651221000, "tid": 120847, "pn": 4}}', 1545651221000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-cs_scientist-ics353', 'stk-cs_scientist', 'ICS 353', 'doc', '{"docs": [{"id": "stk-dr-f98306", "n": "Dr. Wasfi Al-Khatib", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS353-161\n\nالتحضير : ما يدقق على التأخير، يحضر بالـActivity Sheet غالبًا\n\nطريقة الشرح : شرح ممتاز جدًا و يشدك معه و إذا ركزت معه و كتبت في سلايداته وقت شرحه بتفهم وااااجد من المادة و بتبدع في اختباراته، هو نظامه ينزل السلايدات ناقصة و تعبي الأجوبة معه في الشرح\n\nالكويزات : سهلة و كان أغلبها نسخ لصق من الكويزات القديمة\n\nالمياجر: الميجر الأول كان سهل جدًا، الثاني كان متوسط يميل للسهولة\n\nالفاينلات : الفاينل كان حرييييييييييييييييييييقة، الآفرج فيه كان 47 من 100\n\nالقريد النهائي: A+\n\nالصوت: واضح جدًا و مفهوم\n\nإضافات :\nوصفي يا وصفي، الدكتور هذا ملك، من أفضل الدكاترة اللي مروا علي في الجامعة\nشرح ممتاز + أخلاق عالية + تصحيح ممتاز\nطبعًا الدكتور ما راح يزودك درجات هبل بس بنفس الوقت مهو شديد بالتصحيح\nأيضًا عطانا 6 كويزات ذا الترم و حذف أسوأ 2 منها", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467503-ics353", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/wasfi-al-khatib/98306/19", "user": "CS_Scientist", "ts": 1486094695000, "tid": 98306, "pn": 19}}]}', 1486094695000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-some001-ics353', 'stk-some001', 'ICS 353', 'doc', '{"docs": [{"id": "stk-dr-f98309", "n": "Dr. Nasir Darwish", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أسوأ كائن ممكن تشوفه في حياتك الدراسية!!\n\nلا أخلاق ولا تعامل ولا شرح ولا أيصال معلومة ولا اختبارات عدلة ولا تصحيح ولا تقييم للبروجكت ولا علم حتى ما عنده …\n\nيا شباب والله مو عارف كيف يفتح تاب جديد في انترنت اكسبلورر!!! كان يدرسنا ويب ICS353 … ماهو عارف كيف يفتح تاب جديد\n\nويقعد يحقر في الطلاب ويضحك عليهم مع نفسه على باله محد فاهم حركاته …\n\nنص الكلاس نايمين او مشغولين في جوالاتهم وربعه غايبين والربع الاخير يحاول يفهم اي شيء،، يحاول يطلع بفايدة\n\nيقعد يشرح مع نفسه 24/7 يطالع في السبورة،، يطالع فيك من قفاه اذا جيت تسأل ،، هذا اذا ما كرشك وقلك اسكت خلني اكمل ،، وحتى اذا كمل بينساك انت وسؤال … واذا سالت غالبا يخرش لك جواب منا ولا منا او يقلك مدري\nويا كثر ما يقول i dont know , lets try …\nزي الي مو داري وين الله حاطه\n\nفرق شااااااسع بين مستوى شرحه ومستوى اسئلته في الاختبارات\nوياكثر ما جاب اشياء ما شرحها في الكلاس\nيركز على اشياء تافهة بس لانها تجي كاسئلة صعبة في الاختبار\n\nالشخص هذا مدري اصلا كيف صار مدرس في هذي الجامعة ! مدري كيف صار مدرس (Web devlopment) … مدري اصلا كيف صار مدرس من الاساس … هذا اصلا مو educator material … ما ينفع يصير مدرس من الاساس !!!\n\nبعد كل التعليقات السابقة … والله مو عاقل الي ينزل عنده\nالمادة ذي كنت متأمل فيها وناوي ما اخذ فيها الا الـ A+ … خاصة اني كنت فاهم فيها كثير قبل ما اخذها … لكن بعد ما شفته … والله قتل المادة وقتل آبو أبوها …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1294657-ics353", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-nasir-darwish/98309/27", "user": "some001", "ts": 1385485163000, "tid": 98309, "pn": 27}}]}', 1385485163000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bo_rayan-ics353', 'stk-bo_rayan', 'ICS 353', 'doc', '{"docs": [{"id": "stk-dr-f99591", "n": "Dr. Sabri A. Mahmoud", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "T152 ICS353\n\nالتحضير :\nكل يوم وما يحاسب ع التأخير\n\nطريقة الشرح :\nمن السلايدز… بصراحة شرحه عادي لكن المادة كانت سهلة فكانت ما تفرق معي… باستثناء البارت الأخير الي يتكلم عن np complete الى الان مني عارف أسوي بروف محترم 🙂\n\nالكويزات :\nسهلة بس يبيلك تحضر … غالبا ً تجي نفس الأمثلة الي في السلايدز\n\nالمياجر:\nسهلة إلى أن ينقطع النفس… وحتى تصحيحه مرررة ممتاز لو شاف عندك غلط في النص يمكن بس يخصم بوينت وبيتعبر خطواتك صح… يهمه الخطوات أكثر من الناتج النهائي\n\nالفاينلات :\nكوبي بيست من الأولد اكزام… بس مع ذلك ما جبت فيه درجة طيبة بسبب ان الاولد ماهي محلولة… وهو ما يرضى يحلها لازم انت تحلها وتوريه شغلك\n\nالقريد النهائي: أعطيه B+\n\nالصوت: مش واضح كثير للأسف\n\nإضافات :\nمحترم جدا ً … بسببه أتوقع الـ 353 كانت سهلة … لكن لازم تتدرب وتحل عشان تضمن قريد يعجبك\nما كان يجيب proofs الا نادر … غالبا السؤال كان يجي apply the algorithm\nالأفرج للميجر الأول كان 84 والثاني يمكن 74\nفي الـ 353 أنصح فيه عدا ذلك ما أقدر أفتي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1449639-ics353", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-sabri-a-mahmoud/99591/8", "user": "Bo_Rayan", "ts": 1463651047000, "tid": 99591, "pn": 8}}]}', 1463651047000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kfupmy-axis-ics353', 'stk-kfupmy-axis', 'ICS 353', 'doc', '{"docs": [{"id": "stk-dr-f118620", "n": "Dr. Ahmad Al-Herz", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS353/TERM 192\n(Covid-19 Term)\n\nالتحضير :\nوسط كل كلاس توقيع على ورقة\n\nطريقة الشرح :\nممل جداً، يشرح بنبرة صوت وحدة، يكتب من ورقة عنده بشكل رتيب ويستعمل سليدات وصفي(غير محلولة طبعاً). طريقة شرحه عادية وبعض الأحيان سيئة ما تفهم شي، وفيه مفاهيم كثيرة بالمادة تحسه وهو يشرحها ماهو متمكن فيها(وهذا الصراحة شيء طبيعي لأن المادة ثقيلة وهذي أول مرة يدرسها فما ألومه). المادة معه عموماً كانت 100% self-study.\n\nالكويزات :\nكوزاته متوسطة الصعوبة، تشبه إلى حد كبير كوزات وصفي القديمة للمادة، فلذلك ذاكر كوزات وصفي.\nوسط الترم تحول الوضع أونلاين وصار هو يجهز الأسئلة وكانت تتفاوت، مرات يجيب أسئلة سهلة ومرات يجيب أسئلة ابن أمك إذا حليتها\n\nالمياجر:\nميجر1: كارثة! واحد طلع من الاختبار وهو طالع قال بصوت عالي: “حرام عليك يا دكتور إرحمنا!”، وواحد اليوم الثاني قال له “يا دكتور أنا قدني خايف من درجة الإختبار أكثر من كورونا”(مزح طبعاً). عموما الأسئلة كانت صعبة مقارنة بالاختبارات القديمة. بس تصحيحه مش بطال(يمكن يزودك شوي بس الغالب يعطيك حقك).\nميجر 2 والفينال انلغوا(الحمدلله) علشان كورونا(الله يبعده عنا وعنكم وجميع الأمراض والأسقام يا رب).\n\nالفاينلات :\nانلغى للي عندهم NP، الظاهر الي اخذوه 2 او 3 بس.(أنا ما أخذته طبعاً)\n\nالقريد النهائي:\nC\n\nالصوت:\nواضح بس يجيب النوم\n\nإضافات :\nالدكتور توه كان مخلص الدكتوراة الظاهر وجابوه يدرس المادة هذي فكانت أول تجربه له فيها، يمكن يتحسن بالمستقبل، تعامله معك ما يتعدى مرحلة الطالب والدكتور. نصيحتي لا تاخذ معه 353 إلا إذا انحديت عليه إو إذا كان ما فيه عندك خيار إلا هو والمحمدي(هو جلاد صح بس أهون من جلد المحمدي في 353).", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1525327-ics353", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmad-al-herz/118620/26", "user": "KFUPMY-AXIS", "ts": 1599124605000, "tid": 118620, "pn": 26}}]}', 1599124605000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-salman_al-ghamdi-ics353', 'stk-salman_al-ghamdi', 'ICS 353', 'doc', '{"docs": [{"id": "stk-dr-f118620", "n": "Dr. Ahmad Al-Herz", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS353-202\nترم اونلاين\n\nالتحضير : ما كان يحضر… او انه كان يحضر بالتيمز؟ مدري، المهم انه كان سافط التحضير وما يعطيه اهتمام\nطريقة الشرح : يفتح السلايدات ويبدأ يقرا اللي فيها ويشرح ثم ياخذ سؤال من السلايدات ويفتح النوتس في الايباد ويبدأ يكتب الحل بالايباد… طبعا الشرح ممل والصوت ضعيف وبطيء فيصير الشرح كله ممل.\nالكويزات : ما كان فيه كويزات، وصراحة كان اسوأ قرار اتخذه بالنسبة لمادة تعتمد على الحل والتفكير والمذاكرة زي الالقوريذمز، عوضها بالواجبات اللي كانت طويلة وتاخذ وقت وفتراتها متباعدة فالفائدة منها مش كثيرة زي مثلا الكويزات والواجبات سوا.\nالميد : كان جيد صراحة، عدد اسئلة كويس وكان فيه تنوع في الاسئلة، كلها كانت كتابية طبعا.\nالفاينلات : برضو كان جيد، كان عبارة عن اسئلة تحلها طبعا وجداول تعبيها وحاجات ترسمها وكله على حسب نوعية الدرس اللي يغطيه السؤال طبعا، الالقورذمز ما يصلح لها اختيار من متعدد، بس حل اسئلة وهذي متعتها.\nالقريد النهائي: C\nالصوت: واضح لكن ممل، حتى سرعة x3 ما كنت سريعة كفاية\nإضافات : ما فيه فايدة تحضر لكشر خصوصا مع امتلاء اليوتيوب بمحتوى يشرح كل كونسبت في الالقورذمز، اهمها قناة عبدالباري الله يعزه ويحفظه. انصح الجميع انه يعتمد على نفسه اعتماد تام اذا اخذ 353 مع الحرز، لأن جانب الاستفادة منه بيكون قليل صراحة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1530973-ics353", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmad-al-herz/118620/27", "user": "Salman_Al-Ghamdi", "ts": 1627139336000, "tid": 118620, "pn": 27}}]}', 1627139336000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
